head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gIsurCd;
scwin.gCOM_NM;
scwin.gSchDate;
scwin.gBelngDepCd; //상위부서코드

scwin.gUIsurCd; //update시 팝업에 넘겨주기 위해  필요
scwin.gSelctBasYy; //update시 팝업에 넘겨주기 위해  필요
scwin.gComAbbrv; //update시 팝업에 넘겨주기 위해  필요 
scwin.gExcnt; //update시 팝업에 넘겨주기 위해  필요 

scwin.vScrenID = 'ULDSTF37301.xml';
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gBelngDepCd = js_belngdepcd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
//20250509 밸류업팀에서 '밸류업 우수기업'  유형 추가 요청
//'밸류업 우수기업'지정은 밸류업팀에서만, 다른팀에서 지정 불가
//20250523 유가, 코스닥 공시팀에서 밸류업우수기업목록도 조회함
//선정유형 코드 생성시 유가는 1X,코스닥2X, 밸류업9X 로 만들것

scwin.fn_GetProvider = function() {
    var url = frame.srcUrl;
    var arr = url.split("?");
    //alert(url +"     =      "+ arr);		
    return (arr.length > 1 ? arr[1] : '');
};


//페이지 로딩 시 필요한 변수 초기화
scwin.fn_SetCode = function() {
    //시장구분 셋팅
    scwin.gLdMktTp = js_market;
    $c.stf.showObj(panel_mkt, false);
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2') {
        $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
    } else {
        $c.stf.showObj(pnl_team, false);
        $c.stf.setObjectValue(rdo_MKT_ID, '9');
        if (scwin.gBelngDepCd == "1I00" || scwin.gDepCd == "1I00") {
            //밸류업지원부 

        } else {
            $c.stf.showObj(panel_mkt, true);
        }
    }
    scwin.gLdMktTp = $c.stf.getObjectValue(rdo_MKT_ID);
    dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.Reset();
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.Reset();

    //선정유형
    var url = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=R&CD_ENG_NM=VLUP_AWARD_TP_CD";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    $c.stf.showObj(pnl_1, false); // 표창유형

    if (scwin.fn_GetProvider() == 'POPUPMODE') {
        //회사코드 셋팅
        txb_isur_cd.setValue(scwin.gIsurCd);
        txb_com_abbrv.setValue(scwin.gCOM_NM);
    }

    // 달력
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear() + 1, 10); //다음년도
    var mm = parseInt(ToDay.getMonth(), 10) + 1;
    var str = " ";
    for (var i = yyyy; i >= 2005; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);

    //시상년도 시작일
    cmb_AW_YYYY.CBData = str;
    //시상년도 종료일
    cmb_AW_YYYY_END.CBData = str;
    cmb_AW_YYYY.setSelectedIndex(0);
    txt_SelectBasYy.style.visibility = "hidden";
    $c.stf.setObjectValue(cmb_AW_YYYY, parseInt(ToDay.getYear() - 2, 10));
    $c.stf.setObjectValue(cmb_AW_YYYY_END, parseInt(ToDay.getYear(), 10));

    //시상년도 검색 시작년도 enable 처리
    //cmb_AW_YYYY.Enable = false;

    //시장구분에 따른 유형설정
    //선정유형 코드 생성시 유가는 1X,코스닥2X, 밸류업9X 로 만들것
    if (scwin.gLdMktTp == "1") {
        //유가_선정유형
        label_10.setValue("선정유형");
        str = "^전체,11^공시우수법인,12^우수위원,13^공시우수법인(코스닥),99^밸류업 우수기업";
        $c.cm.setColumnProp(grd_Grid, 'EXCNT_DISCLS_CORP_TP_NM', 'Name', '선정 유형');
        $c.cm.setColumnProp(grd_Grid, 'VLUP_AWARD_TP_NM', 'show', 'true'); //밸류업수상구분코드
        $c.cm.setColumnProp(grd_Grid, 'VLUP_EXCNT_CORP_ORD', 'show', 'false'); //밸류업우수법인순서

    } else if (scwin.gLdMktTp == "2") {
        //코스닥_유형
        label_10.setValue("유형");
        str = "^전체,21^장기성실공시우수,22^실적예측공시우수,23^IR활동우수,24^종합평가우수,25^우수위원,99^밸류업 우수기업";
        $c.cm.setColumnProp(grd_Grid, 'EXCNT_DISCLS_CORP_TP_NM', 'Name', "유형");
        $c.cm.setColumnProp(grd_Grid, 'VLUP_AWARD_TP_NM', 'show', 'true'); //밸류업수상구분코드
        $c.cm.setColumnProp(grd_Grid, 'VLUP_EXCNT_CORP_ORD', 'show', 'false'); //밸류업우수법인순서

    } else {
        $c.stf.showObj(pnl_1, true);
        cmb_DEP_CD.setDisabled(true);
        $c.cm.setColumnProp(grd_Grid, 'EXCNT_DISCLS_CORP_TP_NM', 'Name', "유형");
        $c.cm.setColumnProp(grd_Grid, 'VLUP_AWARD_TP_NM', 'show', 'true'); //밸류업수상구분코드
        $c.cm.setColumnProp(grd_Grid, 'VLUP_EXCNT_CORP_ORD', 'show', 'true'); //밸류업우수법인순서

        if (scwin.gBelngDepCd == "1I00" || scwin.gDepCd == "1I00") {
            //밸류업지원부 
            str = "99^밸류업 우수기업";
        } else {
            str = "^전체,99^밸류업 우수기업,21^(코)장기성실공시우수,22^(코)실적예측공시우수,23^(코)IR활동우수,24^(코)종합평가우수,25^(코)우수위원,11^(유)공시우수법인,12^(유)우수위원,13^(유)공시우수법인(코스닥)";
        }
    }
    cmb_Excnt.CBData = str;
    cmb_Excnt.setSelectedIndex(0);

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !정보--;
셋팅-- > function() {
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd; // 법인코드				
    scwin.gCOM_NM = $c.frame.path("../").scwin.gComAbbrv; // 회사명
    scwin.gSchDate = $c.frame.path("../").gDtecDate; // 조회일자
    scwin.gExcnt = $c.frame.path("../").scwin.gExcnt; // 유형

};
scwin.fn_Search = function() {
    var vISUR_CD = $c.stf.getObjectValue(txb_isur_cd);
    var vAW_SCH_DD = $c.stf.getObjectValue(cmb_AW_YYYY);
    var vDEP_CD = $c.stf.getObjectValue(cmb_DEP_CD);
    var vEMP_NO = $c.stf.getObjectValue(cmb_EMP_NO);
    var vAW_SCH_DD_END = $c.stf.getObjectValue(cmb_AW_YYYY_END);
    var vExcnt = $c.stf.getObjectValue(cmb_Excnt);
    var vAWARD_CD = $c.stf.getObjectValue(cmb_Award); //표창유형

    //시상년도 날짜체크
    if (!(scwin.fn_DateCheck(vAW_SCH_DD, vAW_SCH_DD_END))) {
        return;
    }
    scwin.gLdMktTp = $c.stf.getObjectValue(rdo_MKT_ID);
    var url = "/ByPass.do?method=listExcellentDisclsCorp";
    url += "&MKT_TP_CD=" + scwin.gLdMktTp;
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&AW_SCH_DD=" + vAW_SCH_DD;
    url += "&AW_SCH_DD_END=" + vAW_SCH_DD_END;
    url += "&EXCNT=" + vExcnt;
    url += "&DEP_CD=" + vDEP_CD;
    url += "&EMP_NO=" + vEMP_NO;
    url += "&BELNG_DEP_CD=" + scwin.gBelngDepCd;
    url += "&AWARD_CD=" + vAWARD_CD;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_DateCheck = function(strt_dd, end_dd) {
    if (Number(strt_dd) > Number(end_dd)) {
        $c.win.alert("시상년도 검색 시작년도가 종료년도보다 큽니다.");
        cmb_AW_YYYY.focus();
        return false;
    }
    return true;
};
scwin.fn_Delete = function(row, colid) {
    if (colid == "DEL" && row > 0) {
        var res = window.confirm("삭제하시겠습니까?");
        if (res) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            var vSELCT_BAS_YY = dts_List.getCellData(row, "SELCT_BAS_YY");
            var vISUR_CD = dts_List.getCellData(row, "ISUR_CD"); /*ORG SRC: dts_Delete.UserStatus(1) = TB_JOB_DELETE;*/ X = TB_JOB_DELETE;
            dts_Delete.setCellData(1, "SELCT_BAS_YY", vSELCT_BAS_YY);
            dts_Delete.setCellData(1, "ISUR_CD", vISUR_CD);
            trs_delete.Action = "/ByPass.do?method=deleteExcntDisclsCorp" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
            trs_delete.KeyName = "toinb_dataid4";
            trs_delete.KeyValue = "JSP(I:pInput=dts_Delete)";
            trs_delete.Post();
        }
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);

        //시상년도 시작일
        var vAW_SCH_DD = $c.stf.getObjectValue(cmb_AW_YYYY);
        //시상년도 종료일
        var vAW_SCH_DD_END = $c.stf.getObjectValue(cmb_AW_YYYY_END);
        if (scwin.gLdMktTp == "1" && (vAW_SCH_DD <= 2005 && 2005 <= vAW_SCH_DD_END)) {
            //2016.03.07_시장구분이 1이고 조회기간에 2004년이 포함되고 시상년도가 2005또는 전체일때
            //2016.04.11_조회기간 삭제에 따라 시장구분이 1이고 시상년도 시작년도, 종료년도에 2005년이 포함될때로 조건변경
            //예외처리로 CJ 자산운용 추가_추후 아래와 같이 발행코드가 없는 법인은 추가 불가라는 답변을 박주환씨로부터 확인 받음.

            grd_Grid.Redraw = false;
            dts_List.insertRow();
            var nIdx = dts_List.getRowPosition();
            dts_List.setCellData(nIdx, "ISUR_CD", "-");
            dts_List.setCellData(nIdx, "COM_ABBRV", "CJ자산운용");
            dts_List.setCellData(nIdx, "SELCT_BAS_YY", "2004");
            dts_List.setCellData(nIdx, "EXCNT_DISCLS_CORP_AWARD_YY", "2005");
            dts_List.setCellData(nIdx, "EXCNT_DISCLS_CORP_TP_NM", "우수위원");
            dts_List.setCellData(nIdx, "LD_MKT_TP_CD", "1");
            $c.stf.FillGridHeaderTotalCnt(rowcount + 1, panel_page);
            dts_List.setRowPosition(0, 0);
            grd_Grid.Redraw = true;
        }
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    scwin.gDepCd = $c.stf.getObjectValue(cmb_DEP_CD); //;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
};
scwin.dts_EMP_NO_OnFilter = function(row) {
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_EMP_NO.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "우수공시", "", "8");
};
scwin.btn_Input_onclick = async function() {
    params = "input";
    await $c.frame.CreateDialogFrame("gform", "/dsclmgt/ULDSTF37409.gfm", "우수공시법인 등록", 300, 100, 580, 330, "window");
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (colid == "DEL") {
        scwin.fn_Delete(row, colid);
    } else if (colid == "SELCT_BAS_YY" || colid == "EXCNT_DISCLS_CORP_AWARD_YY" || colid == "EXCNT_DISCLS_CORP_TP_NM") {
        //gCondStat = "U";

        //발행기관코드
        scwin.gUIsurCd = dts_List.getCellData(row, "ISUR_CD");
        //선정기준년도
        scwin.gSelctBasYy = dts_List.getCellData(row, "SELCT_BAS_YY");
        //회사명
        scwin.gComAbbrv = dts_List.getCellData(row, "COM_ABBRV");
        //유형
        scwin.gExcnt = dts_List.getCellData(row, "EXCNT_DISCLS_CORP_TP_CD");
        if (scwin.gLdMktTp != "9") {
            //밸류업지원부가 아닌경우 상세보기 불가
            if (dts_List.getCellData(row, "LD_MKT_TP_CD") == "9") {
                $c.win.alert("밸류업 우수기업은 수정하실 수 없습니다.");
                return;
            }
        }
        if (scwin.gUIsurCd.length == 5) {
            params = "update";
            await $c.frame.CreateDialogFrame("gform", "/dsclmgt/ULDSTF37409.gfm", "우수공시법인 수정", 300, 100, 580, 330, "window");
        }
    }
};
scwin.cmb_AW_YYYY_END_OnSelChange = function() {
    //var vAW_YYYY_END = getObjectValue(cmb_AW_YYYY_END);

    //setObjectValue(cmb_AW_YYYY, parseInt(Number(vAW_YYYY_END)-2, 10));

};
scwin.cmb_Excnt_OnSelChange = function() {
    var ExcntVal = $c.stf.getObjectValue(cmb_Excnt);
    if (ExcntVal == '99') {
        //밸류업 우수기업 유형 선택시 
        $c.stf.showObj(pnl_1, true);
    } else {
        $c.stf.showObj(pnl_1, false);
    }
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.showObj(panel_mkt, false);
    fn_GetParentValue();
    scwin.fn_SetCode();
    //회사정보 로딩
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_Search();
};
